import { useContext, useEffect, useState, useCallback } from 'react';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import { useNavigate, useParams } from 'react-router-dom';
import axios from 'axios';
import './messages.scss';

const Messages = () => {
  const { currentUser } = useContext(AuthContext);
  const { darkMode } = useContext(DarkModeContext);
  const { userId } = useParams();
  const navigate = useNavigate();
  const [friends, setFriends] = useState([]);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchFriends = useCallback(async () => {
    const token = localStorage.getItem('token');
    if (!token) {
      setError('Please log in to view friends.');
      return;
    }

    try {
      console.log(`Messages: Fetching friends for user ID: ${currentUser?._id}`);
      const res = await axios.get(`http://localhost:5000/api/users/${currentUser._id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      console.log('Messages: Fetched friends=', JSON.stringify(res.data.friends, null, 2));
      res.data.friends.forEach(friend => {
        console.log(`Messages: Friend ${friend.name} profilePicture=`, friend.profilePicture);
      });
      setFriends(res.data.friends || []);
    } catch (err) {
      console.error('Messages: Error fetching friends:', err.message);
      console.error('Messages: Response:', err.response?.data);
      setError(err.response?.data?.message || 'Failed to load friends.');
    } finally {
      setLoading(false);
    }
  }, [currentUser]);

  const fetchMessages = useCallback(async () => {
    if (!userId) return;
    const token = localStorage.getItem('token');
    if (!token) {
      setError('Please log in to view messages.');
      return;
    }

    try {
      console.log(`Messages: Fetching messages for friend ID: ${userId}`);
      const res = await axios.get(`http://localhost:5000/api/messages/${userId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      console.log('Messages: Fetched messages=', JSON.stringify(res.data, null, 2));
      setMessages(res.data || []);
    } catch (err) {
      console.error('Messages: Error fetching messages:', err.message);
      console.error('Messages: Response:', err.response?.data);
      setError(err.response?.data?.message || 'Failed to load messages.');
    }
  }, [userId]);

  const sendMessage = async (e) => {
    e.preventDefault();
    if (!newMessage.trim() || !userId) return;

    const token = localStorage.getItem('token');
    if (!token) {
      setError('Please log in to send messages.');
      return;
    }

    try {
      console.log(`Messages: Sending message to user ID: ${userId}`);
      const res = await axios.post(
        'http://localhost:5000/api/messages',
        {
          recipientId: userId,
          content: newMessage,
        },
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );
      console.log('Messages: Message sent=', JSON.stringify(res.data, null, 2));
      setMessages([...messages, res.data]);
      setNewMessage('');
    } catch (err) {
      console.error('Messages: Error sending message:', err.message);
      console.error('Messages: Response:', err.response?.data);
      setError(err.response?.data?.message || 'Failed to send message.');
    }
  };

  useEffect(() => {
    if (!currentUser) {
      navigate('/login');
      return;
    }
    console.log('Messages: Rendering with currentUser=', JSON.stringify(currentUser, null, 2));
    fetchFriends();
  }, [currentUser, fetchFriends, navigate]);

  useEffect(() => {
    fetchMessages();
    const interval = setInterval(fetchMessages, 5000); // Poll every 5s
    return () => clearInterval(interval);
  }, [fetchMessages]);

  if (loading) return <div>Loading...</div>;
  if (error) return <div className="error">{error}</div>;

  return (
    <div className={`messages ${darkMode ? 'dark' : ''}`}>
      <div className="friends-sidebar">
        <h3>Friends</h3>
        {friends.length === 0 ? (
          <p>No friends yet.</p>
        ) : (
          friends.map((friend) => (
            <div
              key={friend._id}
              className={`friend-item ${userId === friend._id ? 'active' : ''}`}
              onClick={() => navigate(`/messages/${friend._id}`)}
            >
              <img
                src={friend.profilePicture || '/assets/default-avatar.png'}
                alt={`${friend.name}'s avatar`}
                className="friend-avatar"
                onError={(e) => {
                  console.error(`Messages: Failed to load image for ${friend.name}: ${e.target.src}`);
                  e.target.src = '/assets/default-avatar.png';
                }}
              />
              <span>{friend.name}</span>
            </div>
          ))
        )}
      </div>
      <div className="chat-area">
        {!userId ? (
          <p>Select a friend to start chatting.</p>
        ) : (
          <>
            <div className="chat-header">
              <h3>{friends.find((f) => f._id === userId)?.name || 'Chat'}</h3>
            </div>
            <div className="messages-list">
              {messages.length === 0 ? (
                <p>No messages yet.</p>
              ) : (
                messages.map((msg) => (
                  <div
                    key={msg._id}
                    className={`message ${msg.senderId === currentUser._id ? 'sent' : 'received'}`}
                  >
                    <p>{msg.content}</p>
                    <span className="timestamp">
                      {new Date(msg.createdAt).toLocaleTimeString()}
                    </span>
                  </div>
                ))
              )}
            </div>
            <form onSubmit={sendMessage} className="message-input">
              <input
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                placeholder="Type a message..."
                disabled={!userId}
              />
              <button type="submit" disabled={!newMessage.trim() || !userId}>
                Send
              </button>
            </form>
          </>
        )}
      </div>
    </div>
  );
};

export default Messages;
